import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import {
  Activity, AlertTriangle, ArrowLeft, ArrowRight, ArrowUpRight, Bot, BrainCircuit, Building2, Check, ChevronRight,
  CircleUserRound, FileCheck2, Fingerprint, Folder, FolderOpen, GitBranch, LayoutDashboard,
  Link2, LoaderCircle, LockKeyhole, Network, PlugZap, Plus, RefreshCw, RotateCcw, Search, Settings2,
  Shield, ShieldCheck, ShieldOff, Square, Users, Workflow, X
} from 'lucide-react';
import type { ControlPlaneCanonicalState, WorkGraph, WorkGraphNode } from '@h2a/contracts';
import type { EmployeeWorkspaceApi, EmployeeWorkspaceSnapshot } from '../../../../../../packages/contracts/src/employeeWorkspace';
import type { OfficeWorkspaceId } from '../../components/OfficeWorkspaceDrawer';
import {
  graphForGoal, humanName, nodeStatus, providerNames, purposeActor, timeRemaining,
  workPriority, type WorkspaceDepth, type WorkspacePage
} from './workspaceModel';
import { WorkspaceRoomManager } from './WorkspaceRoomManager';
import './workspace.css';

declare global {
  interface Window { h2aEmployee?: EmployeeWorkspaceApi }
}

interface Props {
  canonical?: ControlPlaneCanonicalState;
  connected: boolean;
  loading: boolean;
  error: string;
  onRefresh(): Promise<void>;
  onOpenSurface(surface: OfficeWorkspaceId | 'settings' | 'acceptance' | 'enrollment', goalId?: string): void;
  onEvidence(reference: string): void;
  onProof(purpose: string, humanId: string): void;
  onClassic(): void;
  surface?: { title: string; content: ReactNode; close(): void };
}

const pages = [
  { id: 'canvas', label: 'Agent canvas', icon: Workflow },
  { id: 'workspaces', label: 'Workspaces', icon: FolderOpen },
  { id: 'people', label: 'People & agents', icon: Users },
  { id: 'memory', label: 'Company memory', icon: BrainCircuit },
  { id: 'security', label: 'Security map', icon: Shield }
] as const;
const tabs = ['Flow', 'Context', 'Outputs', 'Decisions'] as const;
type CanvasTab = typeof tabs[number];
type WorkspaceBlocker = { title: string; message: string; action: string; surface: OfficeWorkspaceId };

const connectionCatalog = [
  ['Claude Code', 'Anthropic', 'Native', 'claude-code'], ['Codex', 'OpenAI', 'Native', 'openai-codex'],
  ['Gemini / Antigravity', 'Google', 'Native', 'gemini-antigravity'], ['MCP agent', 'Open protocol', 'Native', 'custom-cli'],
  ['A2A agent', 'Open protocol', 'Connector', 'custom-cli'], ['Azure OpenAI', 'Microsoft', 'Connector', 'custom-cli'],
  ['Amazon Bedrock', 'AWS', 'Connector', 'custom-cli'], ['Vertex AI', 'Google Cloud', 'Connector', 'custom-cli'],
  ['GitHub Copilot', 'GitHub', 'Connector', 'custom-cli'], ['Cursor', 'Anysphere', 'Connector', 'custom-cli'],
  ['Windsurf', 'Cognition', 'Connector', 'custom-cli'], ['LangGraph', 'LangChain', 'Company agent', 'custom-cli'],
  ['CrewAI', 'CrewAI', 'Company agent', 'custom-cli'], ['AutoGen', 'Microsoft', 'Company agent', 'custom-cli'],
  ['OpenAI Agents SDK', 'OpenAI', 'Company agent', 'custom-cli'], ['Semantic Kernel', 'Microsoft', 'Company agent', 'custom-cli'],
  ['Custom CLI', 'Your company', 'Company agent', 'custom-cli'], ['REST / webhook', 'Your company', 'Company agent', 'custom-cli']
] as const;

function locationSelection(): { page: WorkspacePage; goalId?: string } {
  const [rawPage, goalId] = window.location.hash.slice(1).split('/');
  const migrated = rawPage === 'work' ? 'canvas' : rawPage === 'records' ? 'workspaces' : rawPage;
  const page = pages.some((item) => item.id === migrated) ? migrated as WorkspacePage : 'canvas';
  try { return { page, goalId: goalId ? decodeURIComponent(goalId) : undefined }; }
  catch { return { page }; }
}

export function WorkspaceExperience({ canonical: data, connected, loading, error: loadError, onRefresh, onOpenSurface, onEvidence, onProof, onClassic, surface }: Props): React.JSX.Element {
  const [selection, setSelection] = useState(locationSelection);
  const [depth, setDepth] = useState<WorkspaceDepth>('plain');
  const [tab, setTab] = useState<CanvasTab>('Flow');
  const [composer, setComposer] = useState(false);
  const [intent, setIntent] = useState('');
  const [search, setSearch] = useState('');
  const [busy, setBusy] = useState<string>();
  const [error, setError] = useState('');
  const [blocker, setBlocker] = useState<WorkspaceBlocker>();
  const [now, setNow] = useState(Date.now);
  const [selectedNodeId, setSelectedNodeId] = useState<string>();
  const [employee, setEmployee] = useState<EmployeeWorkspaceSnapshot>();
  const [roomManager, setRoomManager] = useState<{ mode: 'rooms' | 'memory'; roomId?: string }>();
  const pending = useRef(new Set<string>());
  const resumeApproval = useRef<string | undefined>(undefined);
  const heading = useRef<HTMLHeadingElement>(null);

  useEffect(() => { const update = () => setSelection(locationSelection()); window.addEventListener('hashchange', update); return () => window.removeEventListener('hashchange', update); }, []);
  useEffect(() => {
    const cancelContinuation = () => { resumeApproval.current = undefined; };
    window.addEventListener('h2a:proof-cancelled', cancelContinuation);
    return () => window.removeEventListener('h2a:proof-cancelled', cancelContinuation);
  }, []);
  useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 10_000); return () => window.clearInterval(timer); }, []);
  useEffect(() => { heading.current?.focus({ preventScroll: true }); }, [selection.page, selection.goalId, composer]);
  useEffect(() => {
    let cancelled = false;
    void window.h2aEmployee?.snapshot().then((next) => { if (!cancelled) setEmployee(next); }).catch(() => undefined);
    return () => { cancelled = true; };
  }, [data?.goal_work_graph?.generated_at]);

  function navigate(page: WorkspacePage, goalId?: string): void {
    resumeApproval.current = undefined;
    window.location.hash = `${page}${goalId ? `/${encodeURIComponent(goalId)}` : ''}`;
    setComposer(false); setError(''); setSelectedNodeId(undefined); setTab('Flow');
  }

  async function command(key: string, action: () => Promise<unknown>, refreshAfter = true): Promise<void> {
    if (!connected || pending.current.has(key)) return;
    pending.current.add(key); setBusy(key); setError(''); setBlocker(undefined);
    try { await action(); if (refreshAfter) await onRefresh(); }
    catch (cause) {
      const message = cause instanceof Error ? cause.message : 'The operation did not complete. Nothing has been marked successful.';
      const problem = blockerFor(message);
      setError(problem.message);
      setBlocker(problem);
      await onRefresh().catch(() => undefined);
    } finally { pending.current.delete(key); setBusy([...pending.current].at(-1)); }
  }

  const goals = data?.goal_work_graph?.goals ?? [];
  const goal = goals.find((item) => item.goal_id === selection.goalId);
  const graph = data && goal ? graphForGoal(data, goal.goal_id) : undefined;
  const organization = data?.organization.organizations.find((item) => item.status === 'active');
  const candidates = data?.goal_work_graph?.candidates ?? [];
  const pendingApprovals = data?.approvals.requests.filter((item) => item.status === 'pending' && Date.parse(item.expires_at) > now) ?? [];
  const selectedNode = graph?.nodes.find((node) => node.node_id === selectedNodeId);
  const selectedRoom = selection.page === 'workspaces' ? employee?.rooms.find((room) => room.room_id === selection.goalId) : undefined;

  async function approveAndRun(resolvedActor?: ReturnType<typeof purposeActor>): Promise<void> {
    if (!graph || !data || !goal || !window.h2a) return;
    const purpose = 'approve collaborative work graph';
    const actor = resolvedActor ?? purposeActor(data.organization, goal.created_by_human_id, purpose, Date.now());
    if (!actor) {
      resumeApproval.current = graph.graph_id;
      onProof(purpose, goal.created_by_human_id);
      return;
    }
    await command('approve-and-run', async () => {
      if (graph.status === 'draft') await window.h2a!.approveWorkGraph({ graph_id: graph.graph_id, expected_revision: graph.revision, actor });
      await window.h2a!.runWorkGraph({ graph_id: graph.graph_id, actor });
    });
  }

  useEffect(() => {
    if (!data || !goal || !graph || resumeApproval.current !== graph.graph_id) return;
    const actor = purposeActor(data.organization, goal.created_by_human_id, 'approve collaborative work graph', Date.now());
    if (!actor) return;
    resumeApproval.current = undefined;
    void approveAndRun(actor);
  }, [data, goal, graph]);

  async function nodeCommand(node: WorkGraphNode, operation: 'renew' | 'cancel' | 'revoke'): Promise<void> {
    if (!graph || !data || !window.h2a) return;
    const purpose = operation === 'revoke' ? 'revoke a mandate' : node.execution_target === 'paired-node' ? 'administer trusted federation peers' : 'approve collaborative work graph';
    const actor = purposeActor(data.organization, goal?.created_by_human_id ?? node.human_owner_id, purpose, Date.now());
    if ((operation === 'renew' || operation === 'revoke' || node.execution_target === 'paired-node') && !actor) { onProof(purpose, goal?.created_by_human_id ?? node.human_owner_id); return; }
    const request = { graph_id: graph.graph_id, node_id: node.node_id, actor };
    await command(`${operation}:${node.node_id}`, () => operation === 'renew'
      ? window.h2a!.renewWorkGraphNode({ ...request, actor: actor! })
      : operation === 'cancel' ? window.h2a!.cancelWorkGraphNode(request) : window.h2a!.revokeWorkGraphNode(request));
  }

  const pageTitle = goal?.title ?? selectedRoom?.title ?? pages.find((item) => item.id === selection.page)!.label;
  const pageDescription = selection.page === 'canvas' ? 'One live view of people, agents, authority, context, and results.'
    : selection.page === 'workspaces' ? 'Projects and team rooms, organized around outcomes.'
      : selection.page === 'people' ? 'Company people and the agents accountable to them.'
        : selection.page === 'memory' ? 'Reviewed knowledge and protected sources, visible only within their access boundary.'
          : 'Authority and work status across the organization.';

  return <div className="h2a-workspace">
    <a className="ws-skip" href="#workspace-main">Skip to work</a>
    <aside className="ws-sidebar" aria-label="Workspace navigation">
      <div className="ws-brand"><Network size={24} /><strong>H2A</strong><span>Agent work</span></div>
      <div className="ws-organization"><span className="ws-org-icon"><LayoutDashboard size={17} /></span><div><strong>{organization?.name ?? 'Your organization'}</strong><small>{employee?.session.department ?? 'Local workspace'}</small></div></div>
      <nav>{pages.map(({ id, label, icon: Icon }) => <button key={id} className={selection.page === id ? 'ws-nav active' : 'ws-nav'} aria-label={label} title={label} aria-current={selection.page === id ? 'page' : undefined} onClick={() => navigate(id)}><Icon size={19} /><span>{label}</span>{id === 'canvas' && pendingApprovals.length > 0 && <b>{pendingApprovals.length}</b>}</button>)}</nav>
      <div className="ws-sidebar-bottom"><button className="ws-nav" onClick={() => onOpenSurface('pairing')}><Link2 size={18} />Connect coworker</button><button className="ws-nav" onClick={() => onOpenSurface('settings')}><Settings2 size={18} />Connections</button><button className="ws-nav" onClick={onClassic}><ShieldCheck size={18} />Control console</button><div className="ws-boundary"><LockKeyhole size={15} /><span>Connected-observed</span></div></div>
    </aside>
    <div className="ws-body">
      <header className="ws-topbar"><form className="ws-ask" onSubmit={(event) => { event.preventDefault(); navigate('canvas'); setComposer(true); }}><label className="sr-only" htmlFor="workspace-intent">Describe the outcome</label><input id="workspace-intent" value={intent} onChange={(event) => setIntent(event.target.value)} placeholder="Ask your agent team to accomplish something..." /><button className="ws-icon" type="submit" aria-label="Create a plan" title="Create a plan"><ArrowRight size={18} /></button></form><div className="ws-depth" role="group" aria-label="Detail level">{(['plain', 'authority', 'proof'] as const).map((value) => <button key={value} aria-pressed={depth === value} className={depth === value ? 'selected' : ''} onClick={() => setDepth(value)}>{value === 'plain' ? 'Simple' : value === 'authority' ? 'Authority' : 'Proof'}</button>)}</div><button className="ws-icon" disabled={!!busy} onClick={() => void command('refresh', onRefresh, false)} aria-label="Refresh workspace" title="Refresh workspace"><RefreshCw size={18} className={busy === 'refresh' ? 'ws-spin' : ''} /></button></header>
      <main id="workspace-main" className="ws-main" aria-busy={loading} tabIndex={-1}>
        {!connected && <div className="ws-notice" role="status"><LockKeyhole size={18} /><span>{loading ? 'Connecting to the trusted local host...' : 'Connection is stale. Records are read-only until the canonical snapshot returns.'}</span><button onClick={() => void onRefresh()}>Reconnect</button></div>}
        {(loadError || error) && <div className="ws-error" role="alert"><strong>The action could not complete.</strong><p>{loadError || error}</p></div>}
        <div className="ws-page-heading"><div>{(goal || selectedRoom) && <button className="ws-back" onClick={() => navigate(goal ? 'canvas' : 'workspaces')}><ArrowLeft size={16} />{goal ? 'Agent canvas' : 'Workspaces'}</button>}<p className="ws-eyebrow">{goal ? 'LIVE COLLABORATION' : selectedRoom ? 'PERSISTENT TEAM ROOM' : organization?.name ?? 'HUMAN-BOUND AGENT OPERATIONS'}</p><h1 ref={heading} tabIndex={-1}>{composer ? 'Create one shared mission' : pageTitle}</h1><p>{goal ? `Started by ${humanName(data!, goal.created_by_human_id)} · ${goal.sensitivity} · ${graph?.nodes.length ?? 0} agent assignments` : selectedRoom ? `${selectedRoom.department} · ${selectedRoom.member_ids.length} people · multiple governed missions` : pageDescription}</p></div>{selection.page === 'canvas' && !composer && <button className="ws-primary" disabled={!connected} onClick={() => setComposer(true)}><Plus size={17} />New mission</button>}</div>
        {loading && !data ? <Empty icon={<LoaderCircle className="ws-spin" />} title="Loading your organization" text="Reading the current signed state." /> : !data ? <Empty title="Workspace unavailable" text="Open this view in the H2A desktop app." /> : composer ? <Composer data={data} intent={intent} busy={!!busy} connected={connected} onOpenProject={() => onOpenSurface('delivery')} onSubmit={(request) => command('compose', async () => { const next = await window.h2a!.composeCollaborativeGoal(request); const created = next.goals.find((item) => item.trace_id === request.trace_id); if (!created) throw new Error('The host did not return the created mission.'); navigate('canvas', created.goal_id); await window.h2a!.proposeWorkGraph({ goal_id: created.goal_id }); })} />
          : selection.page === 'canvas' ? goal ? <MissionRoom data={data} goal={goal} graph={graph} tab={tab} depth={depth} now={now} busy={busy} connected={connected} selectedNode={selectedNode} onTab={setTab} onSelectNode={setSelectedNodeId} onApproveRun={() => void approveAndRun()} onNodeCommand={nodeCommand} onOpenSurface={onOpenSurface} onEvidence={onEvidence} />
            : <CanvasHome data={data} goals={goals} candidates={candidates} pendingApprovals={pendingApprovals.length} onCreate={() => setComposer(true)} onGoal={(id) => navigate('canvas', id)} onAgents={() => onOpenSurface('agents')} onApprovals={() => onOpenSurface('approvals')} />
          : selection.page === 'workspaces' ? selectedRoom ? <RoomWorkspace data={data} employee={employee} room={selectedRoom} goals={goals} onGoal={(id) => navigate('canvas', id)} onCreate={() => { navigate('canvas'); setComposer(true); }} onManage={() => setRoomManager({ mode: 'rooms', roomId: selectedRoom.room_id })} /> : <Workspaces data={data} employee={employee} goals={goals} onGoal={(id) => navigate('canvas', id)} onRoom={(id) => navigate('workspaces', id)} onRegister={() => onOpenSurface('delivery')} onManageRooms={() => setRoomManager({ mode: 'rooms' })} />
            : selection.page === 'people' ? <People data={data} candidates={candidates} employee={employee} search={search} setSearch={setSearch} depth={depth} onManage={() => onOpenSurface('organization')} onAgents={() => onOpenSurface('agents')} onPair={() => onOpenSurface('pairing')} />
              : selection.page === 'memory' ? <MemoryNetwork data={data} employee={employee} depth={depth} onManage={() => setRoomManager({ mode: 'memory', roomId: employee?.rooms[0]?.room_id })} onContext={() => onOpenSurface('context')} />
                : <SecurityMap data={data} employee={employee} depth={depth} onSecurity={() => onOpenSurface('security')} onEvidence={onEvidence} onAcceptance={() => onOpenSurface('acceptance')} />}
      </main>
    </div>
    {surface && <WorkspaceSurface title={surface.title} onClose={surface.close}>{surface.content}</WorkspaceSurface>}
    {roomManager && !surface && data && <WorkspaceSurface title={roomManager.mode === 'memory' ? 'Reviewed Memory' : 'Team rooms'} onClose={() => setRoomManager(undefined)}><WorkspaceRoomManager canonical={data} snapshot={employee} initialRoomId={roomManager.roomId} initialMode={roomManager.mode} onChange={setEmployee} /></WorkspaceSurface>}
    {blocker && !surface && <WorkspaceSurface title={blocker.title} onClose={() => setBlocker(undefined)}><div className="ws-blocker-sheet"><AlertTriangle size={28} /><div><h3>{blocker.title}</h3><p>{blocker.message}</p><small>Your completed work and evidence remain unchanged.</small></div><button className="ws-primary" onClick={() => { const destination = blocker.surface; setBlocker(undefined); onOpenSurface(destination); }}>{blocker.action}<ChevronRight size={16} /></button></div></WorkspaceSurface>}
  </div>;
}

function CanvasHome({ data, goals, candidates, pendingApprovals, onCreate, onGoal, onAgents, onApprovals }: { data: ControlPlaneCanonicalState; goals: NonNullable<ControlPlaneCanonicalState['goal_work_graph']>['goals']; candidates: NonNullable<ControlPlaneCanonicalState['goal_work_graph']>['candidates']; pendingApprovals: number; onCreate(): void; onGoal(id: string): void; onAgents(): void; onApprovals(): void }): React.JSX.Element {
  const active = [...goals].filter((item) => !['completed', 'cancelled'].includes(item.status)).sort((a, b) => Date.parse(b.updated_at) - Date.parse(a.updated_at));
  return <><section className="ws-launch"><div><span className="ws-live-dot" />{candidates.filter((item) => item.status === 'ready').length} agents ready</div><h2>Give the team an outcome. H2A builds the governed route.</h2><p>Agents continue through dependency-ready work while identity, mandates, context, approvals, and output hashes remain visible.</p><button className="ws-primary" onClick={onCreate}><Plus size={18} />Create a mission</button></section><div className="ws-swarm" aria-label="Available agent team"><div className="ws-swarm-core"><Workflow size={32} /><strong>Agent team</strong><small>{data.organization.memberships.filter((item) => item.status === 'active').length} accountable people</small></div>{candidates.slice(0, 8).map((agent, index) => <button key={agent.candidate_id} className={`ws-swarm-agent orbit-${index + 1}`} onClick={onAgents} title={`Inspect ${agent.display_name}`}><Bot size={21} /><span><strong>{agent.display_name}</strong><small>{providerNames[agent.provider]} · {agent.status}</small></span></button>)}</div><div className="ws-overview"><div><span>Open missions</span><strong>{active.length}</strong></div><div><span>Agents ready</span><strong>{candidates.filter((item) => item.status === 'ready').length}</strong></div><div><span>Decisions waiting</span><strong>{pendingApprovals}</strong></div><div><span>Completed</span><strong>{goals.filter((item) => item.status === 'completed').length}</strong></div></div>{pendingApprovals > 0 && <button className="ws-attention-row" onClick={onApprovals}><Fingerprint size={20} /><span><strong>{pendingApprovals} human decision{pendingApprovals === 1 ? '' : 's'} waiting</strong><small>Open the exact protected action and decide in place.</small></span><ChevronRight size={18} /></button>}<div className="ws-section-heading"><h2>Active missions</h2><span>{goals.length} total</span></div>{active.length === 0 ? <Empty title="No active mission" text="Create one outcome and review the proposed agents, permissions, and dependencies." /> : active.map((item) => <button className="ws-work-row" key={item.goal_id} onClick={() => onGoal(item.goal_id)}><span className={`ws-work-icon ${item.status}`}><GitBranch size={20} /></span><span className="ws-work-description"><strong>{item.title}</strong><small>{humanName(data, item.created_by_human_id)} · {graphForGoal(data, item.goal_id)?.nodes.length ?? 0} assignments</small></span><span className={`ws-status ${item.status}`}>{item.status}</span><ChevronRight size={18} /></button>)}</>;
}

function MissionRoom({ data, goal, graph, tab, depth, now, busy, connected, selectedNode, onTab, onSelectNode, onApproveRun, onNodeCommand, onOpenSurface, onEvidence }: { data: ControlPlaneCanonicalState; goal: NonNullable<ControlPlaneCanonicalState['goal_work_graph']>['goals'][number]; graph?: WorkGraph; tab: CanvasTab; depth: WorkspaceDepth; now: number; busy?: string; connected: boolean; selectedNode?: WorkGraphNode; onTab(tab: CanvasTab): void; onSelectNode(id?: string): void; onApproveRun(): void; onNodeCommand(node: WorkGraphNode, operation: 'renew' | 'cancel' | 'revoke'): Promise<void>; onOpenSurface(surface: OfficeWorkspaceId, goalId?: string): void; onEvidence(reference: string): void }): React.JSX.Element {
  if (!graph) return <Empty icon={<GitBranch />} title="Building the work graph" text="Planning checks registered agents and project boundaries." action={<button className="ws-primary" onClick={() => onOpenSurface('tasks', goal.goal_id)}>Open planner</button>} />;
  const runnable = graph.nodes.some((node) => ['ready', 'failed', 'cancelled'].includes(node.status) && Date.parse(node.mandate_expires_at) > now);
  return <><div className="ws-room-bar"><div className="ws-tabs" role="tablist" aria-label="Mission view">{tabs.map((value) => <button key={value} role="tab" aria-selected={tab === value} className={tab === value ? 'selected' : ''} onClick={() => onTab(value)}>{value}</button>)}</div><span className={`ws-status ${graph.status}`}>{graph.status === 'draft' ? 'Review needed' : graph.status}</span></div>{(graph.status === 'draft' || runnable) && <div className="ws-review-band"><ShieldCheck size={22} /><div><strong>{graph.status === 'draft' ? 'One review starts the governed workflow' : 'Ready work can continue automatically'}</strong><p>H2A stops at human decisions, unavailable providers, expired authority, or failed validation.</p></div><button className="ws-secondary" disabled={!connected} onClick={() => onOpenSurface('tasks', goal.goal_id)}>Edit plan</button><button data-control-id="workspace.plan.approve-run" className="ws-primary" disabled={!connected || !!busy} onClick={onApproveRun}>{busy === 'approve-and-run' ? <LoaderCircle className="ws-spin" size={17} /> : <ArrowRight size={17} />}{graph.status === 'draft' ? 'Approve & start' : 'Continue ready work'}</button></div>}{tab === 'Flow' && <div className="ws-canvas-layout"><AgentGraph data={data} graph={graph} now={now} selectedNodeId={selectedNode?.node_id} onSelect={onSelectNode} /><aside className="ws-live-feed"><div className="ws-section-heading"><h2>Live activity</h2><Activity size={17} /></div>{graph.nodes.map((node) => <button key={node.node_id} onClick={() => onSelectNode(node.node_id)}><span className={`ws-event-dot ${node.status}`} /><span><strong>{node.title}</strong><small>{nodeStatus(node, now)} · {humanName(data, node.human_owner_id)}</small></span></button>)}</aside></div>}{tab === 'Context' && <div className="ws-context-grid">{graph.nodes.map((node) => <article className="ws-context-item" key={node.node_id}><span className="ws-provider">{providerNames[node.provider]}</span><h3>{node.title}</h3><div className="ws-allowed"><Check size={16} /><div><strong>Can receive</strong><p>{node.allowed_context_fields.join(', ') || 'No protected fields'}</p></div></div><div className="ws-withheld"><LockKeyhole size={16} /><div><strong>Kept back</strong><p>{node.withheld_context_fields.join(', ') || 'Everything outside the approved scope'}</p></div></div>{depth === 'proof' && <Proof values={{ 'Context Grant': node.context_grant_id, Passport: node.passport_id }} />}</article>)}</div>}{tab === 'Outputs' && <>{graph.nodes.map((node) => <article className="ws-receipt" key={node.node_id}><FileCheck2 size={21} /><div><h3>{node.title}</h3><p>{node.output_hash ? 'Signed output reference recorded' : nodeStatus(node, now)}</p><p>{node.expected_outputs.join(' · ')}</p>{depth === 'proof' && <Proof values={{ Output: node.output_ref, Hash: node.output_hash, Trace: graph.trace_id }} />}</div><button className="ws-secondary" onClick={() => onEvidence(node.output_hash ?? graph.trace_id)}>Receipt</button></article>)}</>}{tab === 'Decisions' && <><article className="ws-receipt"><Fingerprint size={21} /><div><h3>{graph.approved_by_human_id ? `Approved by ${humanName(data, graph.approved_by_human_id)}` : 'Plan approval is waiting'}</h3><p>Revision {graph.revision}. Any change requires a new exact decision.</p>{depth === 'proof' && <Proof values={{ 'Plan hash': graph.plan_hash, 'Human Proof': graph.approved_human_proof_id }} />}</div><button className="ws-secondary" onClick={() => onOpenSurface('approvals')}>Open decisions</button></article>{graph.approval_checkpoints.map((checkpoint) => <article className="ws-receipt" key={checkpoint.checkpoint_id}><ShieldCheck size={20} /><div><h3>{checkpoint.proof_purpose}</h3><p>{checkpoint.status}</p></div></article>)}</>}{selectedNode && <NodeInspector data={data} graph={graph} node={selectedNode} now={now} depth={depth} busy={busy} connected={connected} onClose={() => onSelectNode(undefined)} onCommand={onNodeCommand} onEvidence={onEvidence} />}{depth === 'proof' && <div className="ws-proof-footer"><Proof values={{ Trace: graph.trace_id, 'Work graph': graph.graph_id, 'Plan hash': graph.plan_hash }} /><button className="ws-secondary" onClick={() => onEvidence(graph.trace_id)}>Reconstruct mission<ArrowUpRight size={16} /></button></div>}</>;
}

function AgentGraph({ data, graph, now, selectedNodeId, onSelect }: { data: ControlPlaneCanonicalState; graph: WorkGraph; now: number; selectedNodeId?: string; onSelect(id: string): void }): React.JSX.Element {
  const layout = useMemo(() => graphLayout(graph), [graph]);
  return <div className="ws-agent-canvas" role="group" aria-label="Human and agent work graph"><div className="ws-canvas-scroll" style={{ minWidth: layout.width, minHeight: layout.height }}><svg viewBox={`0 0 ${layout.width} ${layout.height}`} aria-hidden="true">{layout.links.map((link) => <path key={link.id} d={`M${link.x1},${link.y1} C${link.x1 + 75},${link.y1} ${link.x2 - 75},${link.y2} ${link.x2},${link.y2}`} className={link.active ? 'active' : ''} />)}</svg>{layout.humans.map((human) => <div className="ws-graph-human" style={{ left: human.x, top: human.y }} key={human.id}><CircleUserRound size={22} /><span><strong>{humanName(data, human.id)}</strong><small>Authority owner</small></span></div>)}{layout.nodes.map(({ node, x, y }) => <button key={node.node_id} className={`ws-graph-agent ${selectedNodeId === node.node_id ? 'selected' : ''}`} style={{ left: x, top: y }} onClick={() => onSelect(node.node_id)}><span className={`ws-provider-mark provider-${node.provider}`}><Bot size={19} /></span><span><strong>{node.title}</strong><small>{providerNames[node.provider]} · {nodeStatus(node, now)}</small></span><span className={`ws-event-dot ${node.status}`} /></button>)}</div></div>;
}

function Workspaces({ data, employee, goals, onGoal, onRoom, onRegister, onManageRooms }: { data: ControlPlaneCanonicalState; employee?: EmployeeWorkspaceSnapshot; goals: NonNullable<ControlPlaneCanonicalState['goal_work_graph']>['goals']; onGoal(id: string): void; onRoom(id: string): void; onRegister(): void; onManageRooms(): void }): React.JSX.Element { return <><div className="ws-section-heading"><h2>Team rooms</h2><button className="ws-primary" onClick={onManageRooms}><Plus size={16} />Create room</button></div><p className="ws-section-intro">A room keeps the same people, agents, files, decisions, and Memory across many missions.</p><div className="ws-folder-grid">{employee?.rooms.map((room) => <button className="ws-folder" key={room.room_id} onClick={() => onRoom(room.room_id)}><span className="ws-folder-tab" /><Users size={29} /><strong>{room.title}</strong><small>{room.department} · {room.member_ids.length} people · {room.goal_ids?.length ?? 0} missions</small><span>Open collaboration room<ChevronRight size={16} /></span></button>)}{!employee?.rooms.length && <Empty title="No team room" text="Create one persistent room for a team, its agents, and all related missions." />}</div><div className="ws-section-heading ws-subheading"><h2>Connected projects</h2><button className="ws-secondary" onClick={onRegister}><Plus size={16} />Connect project</button></div><div className="ws-workspace-list">{data.project_delivery.projects.map((project) => { const projectGoals = goals.filter((goal) => goal.project_id === project.project_id); const active = [...projectGoals].sort((a, b) => workPriority(a.status) - workPriority(b.status))[0]; return <button className="ws-project-row" key={project.project_id} onClick={() => active ? onGoal(active.goal_id) : onRegister()}><Folder size={21} /><span><strong>{project.display_name}</strong><small>{projectGoals.length} missions · {project.repository_mode}</small></span><ChevronRight size={16} /></button>; })}</div></>; }

function RoomWorkspace({ data, employee, room, goals, onGoal, onCreate, onManage }: { data: ControlPlaneCanonicalState; employee?: EmployeeWorkspaceSnapshot; room: EmployeeWorkspaceSnapshot['rooms'][number]; goals: NonNullable<ControlPlaneCanonicalState['goal_work_graph']>['goals']; onGoal(id: string): void; onCreate(): void; onManage(): void }): React.JSX.Element {
  const members = (employee?.people ?? []).filter((person) => room.member_ids.includes(person.membership_id));
  const linkedGoals = goals.filter((goal) => room.goal_ids?.includes(goal.goal_id) || room.project_ids?.includes(goal.project_id));
  const linkedGraphs = linkedGoals.map((goal) => graphForGoal(data, goal.goal_id)).filter((graph): graph is WorkGraph => Boolean(graph));
  const roomAgents = [...new Map(linkedGraphs.flatMap((graph) => graph.nodes).map((node) => [node.agent_id, node])).values()];
  const roomMemory = employee?.memory.filter((item) => item.room_id === room.room_id) ?? [];
  return <><section className="ws-room-stage"><header><div><span className="ws-live-dot" />Persistent collaboration room</div><div className="ws-actions"><button className="ws-secondary" onClick={onManage}><Users size={16} />Manage room</button><button className="ws-primary" onClick={onCreate}><Plus size={16} />New mission</button></div></header><div className="ws-room-presence"><section className="ws-room-host"><Building2 size={28} /><strong>{room.department}</strong><small>{linkedGoals.length} linked missions · {roomMemory.length} Memory records</small></section>{members.map((person) => <section key={person.membership_id}><Avatar name={person.display_name} /><strong>{person.display_name}</strong><small>{person.department} · accountable person</small></section>)}{roomAgents.slice(0, 8).map((agent) => <section key={agent.agent_id}><Bot size={28} /><strong>{agent.title}</strong><small>{providerNames[agent.provider]} · {agent.status}</small></section>)}</div></section><div className="ws-room-columns"><section><div className="ws-section-heading"><h2>Missions in this room</h2><span>{linkedGoals.length}</span></div>{linkedGoals.map((goal) => <button className="ws-work-row" key={goal.goal_id} onClick={() => onGoal(goal.goal_id)}><span className={`ws-work-icon ${goal.status}`}><GitBranch size={19} /></span><span className="ws-work-description"><strong>{goal.title}</strong><small>{graphForGoal(data, goal.goal_id)?.nodes.length ?? 0} agent assignments · {goal.status}</small></span><ChevronRight size={17} /></button>)}{linkedGoals.length === 0 && <Empty title="No mission linked yet" text="Create one mission inside this room. The same membership and reviewed Memory remain available." />}</section><aside><h2>Room knowledge</h2>{roomMemory.map((item) => <article key={item.memory_id}><FileCheck2 size={17} /><span><strong>{item.title}</strong><small>{item.status} · revision {item.revision}</small></span></article>)}{roomMemory.length === 0 && <p>No reviewed Memory is linked yet.</p>}</aside></div></>;
}

function People({ data, candidates, employee, search, setSearch, depth, onManage, onAgents, onPair }: { data: ControlPlaneCanonicalState; candidates: NonNullable<ControlPlaneCanonicalState['goal_work_graph']>['candidates']; employee?: EmployeeWorkspaceSnapshot; search: string; setSearch(value: string): void; depth: WorkspaceDepth; onManage(): void; onAgents(): void; onPair(): void }): React.JSX.Element {
  const [view, setView] = useState<'people' | 'teams' | 'agents'>('people');
  const [audience, setAudience] = useState<'team' | 'rooms' | 'organization'>('team');
  const query = search.toLowerCase();
  const roomMemberIds = new Set(employee?.rooms.flatMap((room) => room.member_ids) ?? []);
  const visibleBase = data.organization.memberships.filter((member) => audience === 'organization' && employee?.session.administrator
    ? true : audience === 'rooms' ? roomMemberIds.has(member.membership_id) : member.department === employee?.session.department);
  const members = visibleBase.filter((member) => `${humanName(data, member.human_id)} ${member.department}`.toLowerCase().includes(query));
  const teams = [...new Set(visibleBase.map((member) => member.department))].sort();
  const catalog = connectionCatalog.filter(([name, vendor]) => `${name} ${vendor}`.toLowerCase().includes(query));
  return <><div className="ws-directory-toolbar"><div className="ws-tabs" role="tablist" aria-label="Company directory view">{(['people', 'teams', 'agents'] as const).map((item) => <button role="tab" aria-selected={view === item} className={view === item ? 'selected' : ''} key={item} onClick={() => setView(item)}>{item === 'agents' ? 'Agent connections' : item[0].toUpperCase() + item.slice(1)}</button>)}</div><div className="ws-actions"><button className="ws-secondary" onClick={onPair}><Link2 size={16} />Add coworker</button><button className="ws-primary" onClick={onAgents}><Plus size={16} />Connect agent</button></div></div><div className="ws-audience" role="group" aria-label="Directory visibility"><span>View</span><button className={audience === 'team' ? 'selected' : ''} onClick={() => setAudience('team')}>My team</button><button className={audience === 'rooms' ? 'selected' : ''} onClick={() => setAudience('rooms')}>My rooms</button>{employee?.session.administrator && <button className={audience === 'organization' ? 'selected' : ''} onClick={() => setAudience('organization')}>Organization</button>}<small>Visibility does not grant authority</small></div><label className="ws-search ws-directory-search"><Search size={17} /><input aria-label="Find people, teams, or agents" placeholder="Find people, teams, or agent platforms" value={search} onChange={(event) => setSearch(event.target.value)} /></label>{view === 'people' && <div className="ws-people-grid">{members.map((member) => { const displayName = humanName(data, member.human_id); const showcase = displayName.startsWith('[DEMO]'); return <section className="ws-person-panel" key={member.membership_id}><header><Avatar name={displayName.replace('[DEMO] ', '')} /><div><h2>{displayName}</h2><p>{member.department}</p></div><span className={`ws-status ${showcase ? 'showcase' : member.status}`}>{showcase ? 'view only' : member.status}</span></header><div className="ws-agent-stack">{candidates.filter((agent) => agent.human_owner_id === member.human_id).map((agent) => <button key={agent.candidate_id} onClick={onAgents}><Bot size={20} /><span><strong>{agent.display_name}</strong><small>{providerNames[agent.provider]} · {agent.execution_target === 'paired-node' ? 'Coworker node' : 'Local'}</small></span><span className={`ws-event-dot ${agent.status}`} /></button>)}{!candidates.some((agent) => agent.human_owner_id === member.human_id) && <p>{showcase ? 'Showcase profile only. This person cannot supply Human Proof.' : 'No planning agent is currently available.'}</p>}</div>{depth !== 'plain' && <div className="ws-authority-line"><Fingerprint size={15} />Human identity → membership → agent passport</div>}{depth === 'proof' && <Proof values={{ Human: member.human_id, Membership: member.membership_id }} />}</section>; })}</div>}{view === 'teams' && <div className="ws-team-grid">{teams.filter((team) => team.toLowerCase().includes(query)).map((team) => { const teamMembers = visibleBase.filter((member) => member.department === team); const teamAgents = candidates.filter((agent) => teamMembers.some((member) => member.human_id === agent.human_owner_id)); const rooms = employee?.rooms.filter((room) => room.department === team).length ?? 0; return <section key={team}><Building2 size={24} /><h2>{team}</h2><p>{teamMembers.length} people · {teamAgents.length} agents · {rooms} rooms</p><div>{teamMembers.slice(0, 6).map((member) => <Avatar key={member.membership_id} name={humanName(data, member.human_id).replace('[DEMO] ', '')} />)}</div><button className="ws-secondary" onClick={onPair}>Request collaboration</button></section>; })}</div>}{view === 'agents' && <><div className="ws-catalog-intro"><PlugZap size={23} /><div><strong>Connect personal, enterprise, or company-built agents</strong><p>Native lanes launch through H2A. Connector entries require their real adapter and authentication before becoming ready.</p></div></div><div className="ws-agent-catalog">{catalog.map(([name, vendor, kind, provider]) => { const connectedAgent = candidates.find((agent) => agent.provider === provider && (kind === 'Native' || agent.display_name.toLowerCase().includes(name.toLowerCase()))); return <section key={`${name}-${vendor}`}><span className={`ws-provider-mark provider-${provider}`}><Bot size={19} /></span><div><h2>{name}</h2><p>{vendor} · {kind}</p></div><span className={`ws-status ${connectedAgent?.status ?? 'not-connected'}`}>{connectedAgent ? connectedAgent.status : 'available'}</span><button className="ws-secondary" onClick={onAgents}>{connectedAgent ? 'Manage' : kind === 'Native' ? 'Connect' : 'Configure'}</button></section>; })}</div></>}<div className="ws-social-band"><Users size={22} /><div><strong>Company directory, without borrowed authority</strong><p>{members.length} coworkers in this view. Showcase profiles are view-only; every real collaboration request still needs signed ownership and approval.</p></div><button className="ws-secondary" onClick={onManage}>Manage authority</button></div></>;
}

function MemoryNetwork({ data, employee, depth, onManage, onContext }: { data: ControlPlaneCanonicalState; employee?: EmployeeWorkspaceSnapshot; depth: WorkspaceDepth; onManage(): void; onContext(): void }): React.JSX.Element { const memory = employee?.memory ?? []; const artifacts = data.context_broker.artifacts; return <><div className="ws-memory-stage"><div className="ws-brain-core"><BrainCircuit size={50} /><strong>Reviewed memory</strong><small>{memory.filter((item) => item.status === 'published').length} published · {memory.filter((item) => item.status === 'draft').length} awaiting review</small></div><div className="ws-memory-nodes">{memory.map((item) => <button className={`ws-memory-node ${item.status}`} key={item.memory_id} title={item.body}><FileCheck2 size={19} /><span><strong>{item.title}</strong><small>{item.status} · revision {item.revision}</small></span>{depth === 'proof' && <code>{item.content_hash.slice(0, 18)}…</code>}</button>)}{artifacts.map((artifact) => <button className="ws-memory-node locked" key={artifact.artifact_id} onClick={onContext} title="Protected source values remain hidden; open Sharing boundaries to request exact fields."><LockKeyhole size={19} /><span><strong>{artifact.name}</strong><small>Protected source · {artifact.status}</small></span>{depth === 'proof' && <code>{artifact.canonical_hash.slice(0, 18)}…</code>}</button>)}</div></div><div className="ws-memory-legend"><span><span className="ws-event-dot succeeded" />Published after review</span><span><span className="ws-event-dot waiting" />Awaiting independent review</span><span><LockKeyhole size={14} />Locked source metadata only</span><div><button className="ws-secondary" onClick={onManage}>Review memory</button><button className="ws-secondary" onClick={onContext}>Sharing boundaries</button></div></div>{memory.length === 0 && artifacts.length === 0 && <Empty title="No reusable knowledge yet" text="Knowledge appears here only after a person submits it and an eligible independent reviewer publishes it." />}</>; }

function SecurityMap({ data, employee, depth, onSecurity, onEvidence, onAcceptance }: { data: ControlPlaneCanonicalState; employee?: EmployeeWorkspaceSnapshot; depth: WorkspaceDepth; onSecurity(): void; onEvidence(reference: string): void; onAcceptance(): void }): React.JSX.Element {
  const [audience, setAudience] = useState<'team' | 'executive' | 'ciso'>('team');
  const organizationMembers = data.organization.memberships.filter((item) => item.status === 'active');
  const activeMembers = audience === 'team' ? organizationMembers.filter((item) => item.department === employee?.session.department) : organizationMembers;
  const activeAgents = (data.goal_work_graph?.candidates ?? []).filter((item) => item.status === 'ready' && activeMembers.some((member) => member.human_id === item.human_owner_id));
  const activeMandates = data.mandates.mandates.filter((item) => item.status === 'active' && (audience !== 'team' || activeAgents.some((agent) => agent.agent_id === item.subject.agentId)));
  const activeGrants = data.context_broker.grants.filter((item) => item.status === 'active' && (audience !== 'team' || activeAgents.some((agent) => agent.agent_id === item.grant.recipient_agent_id)));
  const conductor = data.demonstration_conductor; const conductorPassed = conductor?.steps.filter((item) => item.status === 'passed').length ?? 0;
  return <><div className="ws-audience" role="group" aria-label="Security visibility"><span>View</span><button className={audience === 'team' ? 'selected' : ''} onClick={() => setAudience('team')}>My team</button>{employee?.session.administrator && <><button className={audience === 'executive' ? 'selected' : ''} onClick={() => setAudience('executive')}>Executive</button><button className={audience === 'ciso' ? 'selected' : ''} onClick={() => setAudience('ciso')}>CISO</button></>}<small>{audience === 'ciso' ? 'Containment and proof' : audience === 'executive' ? 'Organization posture' : 'Department scope'}</small></div><div className="ws-security-summary"><div><ShieldCheck size={28} /><span><strong>{data.evidence.integrity.status}</strong><small>Evidence ledger</small></span></div><div><strong>{activeMembers.length}</strong><small>Active people</small></div><div><strong>{activeAgents.length}</strong><small>Ready agents</small></div><div><strong>{activeMandates.length}</strong><small>Active mandates</small></div><div><strong>{activeGrants.length}</strong><small>Active grants</small></div></div><div className="ws-security-map"><section><span className="ws-map-label">{audience === 'team' ? 'Department' : 'Organization'}</span><h2>{audience === 'team' ? employee?.session.department ?? 'Your team' : data.organization.organizations.find((item) => item.status === 'active')?.name ?? 'No active organization'}</h2>{depth === 'proof' && <code>{data.organization.organizations.find((item) => item.status === 'active')?.organization_id}</code>}</section><div className="ws-map-column">{activeMembers.map((member) => <section key={member.membership_id}><CircleUserRound size={20} /><div><strong>{humanName(data, member.human_id)}</strong><small>{member.department}</small></div>{depth === 'proof' && <code>{member.membership_id}</code>}</section>)}</div><div className="ws-map-column agents">{activeAgents.map((agent) => <section key={agent.candidate_id}><Bot size={20} /><div><strong>{agent.display_name}</strong><small>{agent.execution_target} · {agent.status}</small></div>{depth !== 'plain' && <span>{agent.capabilities.length} capabilities</span>}</section>)}</div><div className="ws-map-column controls"><section><LockKeyhole size={20} /><div><strong>Mandates</strong><small>{activeMandates.length} active scopes</small></div></section><section><Fingerprint size={20} /><div><strong>Approvals</strong><small>{data.approvals.requests.filter((item) => item.status === 'pending').length} pending</small></div></section><section><Link2 size={20} /><div><strong>Federation</strong><small>{data.federation.peers.filter((item) => item.status === 'active').length} trusted peers</small></div></section></div></div>{conductor && <div className="ws-notice"><Activity size={18} /><span><strong>HP demonstration: {conductor.status}</strong><br />{conductorPassed}/{conductor.steps.length} evidence-backed steps on {conductor.trace_id}</span></div>}<div className="ws-security-actions"><button className="ws-secondary" onClick={onSecurity}>Run security controls</button><button className="ws-secondary" onClick={() => onEvidence('')}>Investigate evidence</button><button className="ws-primary" onClick={onAcceptance}>{conductor ? 'Continue HP demonstration' : 'Start HP demonstration'}</button></div></>;
}

function NodeInspector({ data, graph, node, now, depth, busy, connected, onClose, onCommand, onEvidence }: { data: ControlPlaneCanonicalState; graph: WorkGraph; node: WorkGraphNode; now: number; depth: WorkspaceDepth; busy?: string; connected: boolean; onClose(): void; onCommand(node: WorkGraphNode, operation: 'renew' | 'cancel' | 'revoke'): Promise<void>; onEvidence(reference: string): void }): React.JSX.Element { const expired = Date.parse(node.mandate_expires_at) <= now; return <WorkspaceSurface title={node.title} onClose={onClose}><div className="ws-inspector-summary"><span className={`ws-provider-mark provider-${node.provider}`}><Bot size={23} /></span><div><strong>{providerNames[node.provider]}</strong><p>{humanName(data, node.human_owner_id)} is accountable · {nodeStatus(node, now)}</p></div></div><p>{node.objective}</p><dl className="ws-inspector-grid"><Fact label="Can use" value={node.allowed_tools.join(', ') || 'No tools'} /><Fact label="Can write" value={node.allowed_paths.join(', ') || 'No filesystem writes'} /><Fact label="Can receive" value={node.allowed_context_fields.join(', ') || 'No protected fields'} /><Fact label="Kept back" value={node.withheld_context_fields.join(', ') || 'Everything else'} /><Fact label="Depends on" value={graph.dependency_edges.filter((edge) => edge.successor_node_id === node.node_id).map((edge) => graph.nodes.find((item) => item.node_id === edge.predecessor_node_id)?.title).filter(Boolean).join(', ') || 'Independent'} /><Fact label="Permission" value={timeRemaining(node.mandate_expires_at, now)} /></dl>{depth !== 'plain' && <Authority node={node} now={now} depth={depth} />}{node.reason_code && <div className="ws-notice"><Activity size={18} /><span><strong>Why it stopped</strong><br />{node.reason_code}</span></div>}<div className="ws-actions">{expired && !['succeeded', 'revoked'].includes(node.status) && <button className="ws-primary" disabled={!connected || !!busy} onClick={() => void onCommand(node, 'renew')}><RotateCcw size={16} />Renew permission</button>}{['running', 'waiting'].includes(node.status) && <button className="ws-secondary" disabled={!connected || !!busy || node.execution_target !== 'local'} onClick={() => void onCommand(node, 'cancel')}><Square size={16} />Pause work</button>}{node.execution_target === 'local' && !['succeeded', 'revoked'].includes(node.status) && <button className="ws-secondary ws-stop" disabled={!connected || !!busy} onClick={() => void onCommand(node, 'revoke')}><ShieldOff size={16} />Withdraw authority</button>}<button className="ws-secondary" onClick={() => onEvidence(node.output_hash ?? graph.trace_id)}>Open receipt</button></div></WorkspaceSurface>; }

function Composer({ data, intent, busy, connected, onOpenProject, onSubmit }: { data: ControlPlaneCanonicalState; intent: string; busy: boolean; connected: boolean; onOpenProject(): void; onSubmit(request: Parameters<NonNullable<Window['h2a']>['composeCollaborativeGoal']>[0]): Promise<void> }): React.JSX.Element { const [title, setTitle] = useState(intent); const [projectId, setProjectId] = useState(data.project_delivery.projects[0]?.project_id ?? ''); const [humanId, setHumanId] = useState(data.organization.memberships.find((item) => item.status === 'active')?.human_id ?? ''); const [outcome, setOutcome] = useState('Working result\nValidation receipt'); const [sensitivity, setSensitivity] = useState<'internal' | 'public' | 'confidential' | 'restricted'>('internal'); const member = data.organization.memberships.find((item) => item.human_id === humanId && item.status === 'active'); const lines = (value: string) => value.split(/\r?\n/u).map((line) => line.trim()).filter(Boolean); return <form className="ws-composer" onSubmit={(event) => { event.preventDefault(); if (!member) return; void onSubmit({ organization_id: member.organization_id, created_by_human_id: humanId, project_id: projectId, title: title.trim(), objective: title.trim(), outcome: outcome.trim(), expected_outputs: lines(outcome), constraints: [], deadline: null, sensitivity, trace_id: `tr_goal_${crypto.randomUUID()}` }); }}><label className="ws-wide">Outcome<textarea required maxLength={160} value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Build a clothing website with researched content, designed UI, implementation, and QA." /></label><label>Accountable person<select required value={humanId} onChange={(event) => setHumanId(event.target.value)}>{data.organization.memberships.filter((item) => item.status === 'active').map((item) => <option key={item.membership_id} value={item.human_id}>{humanName(data, item.human_id)} · {item.department}</option>)}</select></label><label>Workspace<select required value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="">Choose a registered project</option>{data.project_delivery.projects.map((project) => <option key={project.project_id} value={project.project_id}>{project.display_name}</option>)}</select></label><label className="ws-wide">Done means<textarea required value={outcome} onChange={(event) => setOutcome(event.target.value)} /></label><label>Sensitivity<select value={sensitivity} onChange={(event) => setSensitivity(event.target.value as typeof sensitivity)}>{['public', 'internal', 'confidential', 'restricted'].map((value) => <option key={value}>{value}</option>)}</select></label><div className="ws-composer-footer"><p>Next, review one visual plan showing agent ownership, permissions, and dependencies.</p><button type="button" className="ws-secondary" onClick={onOpenProject}>Register workspace</button><button className="ws-primary" type="submit" disabled={!connected || busy || !member || !projectId || !title.trim() || !outcome.trim()}>{busy ? <LoaderCircle className="ws-spin" size={17} /> : <GitBranch size={17} />}{busy ? 'Building plan...' : 'Review plan'}</button></div></form>; }

function graphLayout(graph: WorkGraph): { width: number; height: number; humans: Array<{ id: string; x: number; y: number }>; nodes: Array<{ node: WorkGraphNode; x: number; y: number }>; links: Array<{ id: string; x1: number; y1: number; x2: number; y2: number; active: boolean }> } { const levels = new Map<string, number>(); const levelOf = (id: string, trail = new Set<string>()): number => { if (levels.has(id)) return levels.get(id)!; if (trail.has(id)) return 0; const predecessors = graph.dependency_edges.filter((edge) => edge.successor_node_id === id).map((edge) => edge.predecessor_node_id); const level = predecessors.length ? Math.max(...predecessors.map((parent) => levelOf(parent, new Set([...trail, id])))) + 1 : 0; levels.set(id, level); return level; }; graph.nodes.forEach((node) => levelOf(node.node_id)); const groups = new Map<number, WorkGraphNode[]>(); graph.nodes.forEach((node) => groups.set(levels.get(node.node_id)!, [...(groups.get(levels.get(node.node_id)!) ?? []), node])); const maxRows = Math.max(1, ...[...groups.values()].map((items) => items.length)); const width = Math.max(760, 330 + (Math.max(0, ...levels.values()) + 1) * 245); const height = Math.max(430, 110 + maxRows * 125); const nodes = graph.nodes.map((node) => { const level = levels.get(node.node_id)!; const group = groups.get(level)!; return { node, x: 285 + level * 245, y: 45 + group.indexOf(node) * 125 }; }); const ownerIds = [...new Set(graph.nodes.map((node) => node.human_owner_id))]; const humans = ownerIds.map((id, index) => ({ id, x: 32, y: 60 + index * Math.max(100, (height - 140) / Math.max(1, ownerIds.length - 1)) })); const links = [...graph.nodes.filter((node) => levels.get(node.node_id) === 0).map((node) => { const from = humans.find((human) => human.id === node.human_owner_id)!; const to = nodes.find((item) => item.node.node_id === node.node_id)!; return { id: `owner-${node.node_id}`, x1: from.x + 165, y1: from.y + 32, x2: to.x, y2: to.y + 38, active: node.status !== 'draft' }; }), ...graph.dependency_edges.map((edge) => { const from = nodes.find((item) => item.node.node_id === edge.predecessor_node_id)!; const to = nodes.find((item) => item.node.node_id === edge.successor_node_id)!; return { id: edge.edge_id, x1: from.x + 195, y1: from.y + 38, x2: to.x, y2: to.y + 38, active: from.node.status === 'succeeded' }; })]; return { width, height, humans, nodes, links }; }

function Authority({ node, now, depth }: { node: WorkGraphNode; now: number; depth: WorkspaceDepth }): React.JSX.Element { return <div className="ws-authority"><p><LockKeyhole size={14} /><strong>Mandate</strong> {timeRemaining(node.mandate_expires_at, now)}</p><p><GitBranch size={14} /><strong>Scope</strong> {node.mandate_scope.actions.join(', ') || 'No actions'} · {node.mandate_scope.paths.join(', ') || 'No writes'}</p>{depth === 'proof' && <Proof values={{ Passport: node.passport_id, Mandate: node.mandate_id, Assignment: node.project_assignment_id }} />}</div>; }
function Proof({ values }: { values: Record<string, string | null | undefined> }): React.JSX.Element { return <dl className="ws-proof">{Object.entries(values).map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value ?? 'Not recorded'}</dd></div>)}</dl>; }
function Fact({ label, value }: { label: string; value: string }): React.JSX.Element { return <div><dt>{label}</dt><dd>{value}</dd></div>; }
function Avatar({ name }: { name: string }): React.JSX.Element { return <span className="ws-human-avatar">{name.split(/\s+/u).map((part) => part[0]).join('').slice(0, 2).toUpperCase()}</span>; }
function Empty({ icon, title, text, action }: { icon?: ReactNode; title: string; text: string; action?: ReactNode }): React.JSX.Element { return <div className="ws-empty">{icon}<h2>{title}</h2><p>{text}</p>{action}</div>; }
function WorkspaceSurface({ title, children, onClose }: { title: string; children: ReactNode; onClose(): void }): React.JSX.Element { const ref = useRef<HTMLDialogElement>(null); useEffect(() => { const active = document.activeElement as HTMLElement | null; ref.current?.showModal(); return () => { ref.current?.close(); active?.focus(); }; }, []); return <dialog ref={ref} className="ws-surface" aria-labelledby="workspace-surface-title" onCancel={(event) => { event.preventDefault(); onClose(); }}><header><div><p className="ws-eyebrow">CONNECTED WORKSPACE</p><h2 id="workspace-surface-title">{title}</h2></div><button className="ws-icon" title="Close" aria-label="Close" onClick={onClose}><X size={21} /></button></header><div className="ws-surface-content">{children}</div></dialog>; }

function blockerFor(message: string): WorkspaceBlocker {
  if (/human proof|biometric|liveness/iu.test(message)) return { title: 'Confirm your identity', message: 'This action needs a fresh verification from the named accountable person.', action: 'Verify and continue', surface: 'organization' };
  if (/approval|approver|quorum/iu.test(message)) return { title: 'A human decision is needed', message: 'The protected action is paused. Review the exact effect and choose an eligible approver.', action: 'Open decision', surface: 'approvals' };
  if (/context grant|context.*expired|leakage/iu.test(message)) return { title: 'Sharing permission needs attention', message: 'The agent does not currently have a valid least-context grant for this step.', action: 'Review sharing', surface: 'context' };
  if (/federation|peer|node|invitation|fingerprint/iu.test(message)) return { title: 'Coworker connection needs attention', message: 'The remote participant is not ready for this action. Review the trust connection and retry here afterward.', action: 'Review connection', surface: 'pairing' };
  if (/project|worktree|resource_not_allowed|allowed path|repository/iu.test(message)) return { title: 'Workspace access needs attention', message: 'The assignment is outside the current project boundary or its workspace is not ready.', action: 'Review workspace', surface: 'delivery' };
  if (/agent|provider|passport|runtime|attestation|mandate|assignment|authority projection|permission/iu.test(message)) return { title: 'Agent permission needs attention', message: 'One agent dependency is missing, expired, or unavailable. Repair only the affected agent, then continue the mission.', action: 'Repair agent', surface: 'agents' };
  return { title: 'This step needs attention', message, action: 'Review mission', surface: 'tasks' };
}
